UPDATE comtccmmncodedetail
   SET code_nm=#{codeNm}, sort_ordr=COALESCE(#{sortOrdr},0), use_yn=COALESCE(#{useYn},'Y')
 WHERE cl_code=#{clCode} AND code=#{code}

