SELECT menu_no AS "menuNo", menu_nm AS "menuNm", menu_url AS "menuUrl",
       upper_menu_no AS "upperMenuNo", menu_ordr AS "menuOrdr", use_yn AS "useYn"
  FROM comtnmenuinfo WHERE menu_no=#{menuNo}
